490	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
491	async function saveStore(file: string, store: Store): Promise<void> {
492	  let json: string;
493	  try {
494	    json = JSON.stringify(store, null, 2) + '\n';
495	  } catch (err) {
496	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
497	  }
498	  const tmp = `${file}.${process.pid}.tmp`;
499	  try {
500	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
501	    await rename(tmp, file);
502	  } catch (err) {
503	    await unlink(tmp).catch(() => {});
504	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
505	  }
506	}
