512	function formatResourceIds(store: Store, ids: string[]): string {
513	  return ids
514	    .map((id) => {
515	      const r = store.resources.find((x) => x.id === id);
516	      return r ? `${id}（${r.name}）` : id;
517	    })
518	    .join('、');
519	}
