521	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
522	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
523	  const problems: string[] = [];
524	  const seen = new Set<string>();
525	  const dupes: string[] = [];
526	  for (const id of rawIds) {
527	    if (seen.has(id)) {
528	      if (!dupes.includes(id)) dupes.push(id);
529	    }
530	    seen.add(id);
531	  }
532	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
533	
534	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
535	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
536	
537	  if (problems.length > 0) throw new BizError(problems.join('\n'));
538	  return [...seen].sort();
539	}
