541	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
542	  return mergeIntervals(
543	    r.open.map(
544	      ([s, e]) =>
545	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
546	    ),
547	  );
