550	// 找出开放区间不能完整覆盖 [startMin, endMin) 的资源
551	function findCoverageGaps(
552	  store: Store,
553	  ids: string[],
554	  startMin: number,
555	  endMin: number,
556	): Array<{id: string; r: ResourceRec}> {
557	  return ids
558	    .map((id) => ({id, r: store.resources.find((x) => x.id === id)!}))
559	    .filter(({r}) => !isFullyCovered(openSegmentsOf(r), startMin, endMin));
560	}
