562	// 校验每个资源的开放区间都能完整覆盖 [startMin, endMin)
563	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
564	  const failing = findCoverageGaps(store, ids, startMin, endMin);
565	  if (failing.length > 0) {
566	    throw new BizError(
567	      '开放时间不足，以下资源的开放区间不能完整覆盖预约区间：\n' +
568	        failing.map(({id, r}) => `- ${id}（${r.name}）`).join('\n'),
569	    );
570	  }
571	}
