578	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
579	function findConflicts(
580	  store: Store,
581	  ids: string[],
582	  startMin: number,
583	  endMin: number,
584	  excludeBookingId?: string,
585	): Conflict[] {
586	  const wanted = new Set(ids);
587	  const conflicts: Conflict[] = [];
588	  for (const b of store.bookings) {
589	    if (b.status !== 'active') continue;
590	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
591	    const bStart = parseDateTime(b.start, '预约开始时间');
592	    const bEnd = parseDateTime(b.end, '预约结束时间');
593	    const overlap = bStart < endMin && startMin < bEnd;
594	    if (!overlap) continue;
595	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
596	    if (shared.length > 0) conflicts.push({booking: b, shared});
597	  }
598	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
599	  return conflicts;
600	}
601	
602	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
603	  if (conflicts.length === 0) return;
604	  const lines = conflicts.map(
605	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
606	  );
607	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
608	}
