614	interface GlobalArgs {
615	  dataFile: string;
616	  help: boolean;
617	  rest: string[];
618	}
619	
620	function splitGlobalArgs(argv: string[]): GlobalArgs {
621	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
622	  for (let i = 0; i < argv.length; i++) {
623	    const a = argv[i];
624	    if (a === '-h' || a === '--help') {
625	      result.help = true;
626	    } else if (a === '--data') {
627	      const v = argv[++i];
628	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
629	      result.dataFile = v;
630	    } else if (a.startsWith('--data=')) {
631	      result.dataFile = a.slice('--data='.length);
632	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
633	    } else {
634	      result.rest.push(a);
635	    }
636	  }
637	  return result;
638	}
