640	interface ParsedFlags {
641	  values: Map<string, string[]>;
642	  positionals: string[];
643	}
644	
645	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
646	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
647	  const allowedSet = new Set(allowed);
648	  const multiSet = new Set(multi);
649	  const values = new Map<string, string[]>();
650	  const positionals: string[] = [];
651	
652	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
653	    if (inline !== undefined) return [inline, index];
654	    const v = args[index + 1];
655	    if (v === undefined || v.startsWith('-')) {
656	      throw new UsageError(`选项 --${key} 缺少值`);
657	    }
658	    return [v, index + 1];
659	  };
660	
661	  for (let i = 0; i < args.length; i++) {
662	    const a = args[i];
663	    if (a.startsWith('--')) {
664	      let key: string;
665	      let inline: string | undefined;
666	      const eq = a.indexOf('=');
667	      if (eq >= 0) {
668	        key = a.slice(2, eq);
669	        inline = a.slice(eq + 1);
670	      } else {
671	        key = a.slice(2);
672	      }
673	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
674	      let v: string;
675	      [v, i] = takeValue(key, inline, i);
676	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
677	      if (!multiSet.has(key) && values.has(key)) {
678	        throw new UsageError(`选项 --${key} 只能指定一次`);
679	      }
680	      const list = values.get(key) ?? [];
681	      list.push(v);
682	      values.set(key, list);
683	    } else if (a.startsWith('-') && a !== '-') {
684	      throw new UsageError(`未知参数: ${a}`);
685	    } else {
686	      positionals.push(a);
687	    }
688	  }
689	  return {values, positionals};
690	}
691	
692	function requireFlag(values: Map<string, string[]>, key: string): string {
693	  const v = values.get(key)?.[0];
694	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
695	  return v;
696	}
