786	async function cmdRescheduleBooking(args: string[]): Promise<void> {
787	  const {values, positionals} = parseFlags(args, ['start', 'end', 'resource'], ['resource']);
788	  if (positionals.length !== 1) {
789	    throw new UsageError('用法: reschedule-booking <预约标识> [--start ...] [--end ...] [--resource ...]');
790	  }
791	  const id = positionals[0];
792	
793	  const file = activeDataFile;
794	  const store = await loadStore(file);
795	  const booking = store.bookings.find((b) => b.id === id);
796	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
797	  if (booking.status === 'cancelled') {
798	    throw new BizError(`预约 ${id} 已取消，不能改期`);
799	  }
800	
801	  const hasTime = values.has('start') || values.has('end');
802	  const hasResource = values.has('resource');
803	  if (!hasTime && !hasResource) {
804	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
805	  }
806	
807	  const startRaw = values.get('start')?.[0] ?? booking.start;
808	  const endRaw = values.get('end')?.[0] ?? booking.end;
809	  const startMin = parseDateTime(startRaw, '预约开始时间');
810	  const endMin = parseDateTime(endRaw, '预约结束时间');
811	  if (endMin <= startMin) {
812	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
813	  }
814	
815	  let ids: string[] = booking.resourceIds;
816	  if (hasResource) {
817	    const resourceArgs = values.get('resource')!;
818	    ids = resolveResourceIds(store, resourceArgs);
819	  }
820	
821	  assertOpenCoverage(store, ids, startMin, endMin);
822	  // 改期检查排除自身
823	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
824	
825	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
826	  // seriesId 不随改期变化：改期后仍属原系列。
827	  booking.start = startRaw;
828	  booking.end = endRaw;
829	  booking.resourceIds = ids;
830	  await saveStore(file, store);
831	  console.log(`已改期预约 ${id}（标识保持不变）`);
832	  if (booking.seriesId) console.log(`  所属系列: ${booking.seriesId}（改期后仍属该系列）`);
833	  console.log(`  时间: ${startRaw} → ${endRaw}`);
834	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
835	}
