873	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
874	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
875	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
876	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
877	  }
878	  const o = raw as Record<string, unknown>;
879	  for (const k of Object.keys(o)) {
880	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
881	  }
882	  if (!Array.isArray(o.items)) {
883	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
884	  }
885	  const items = o.items as unknown[];
886	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
887	
888	  const problems: string[] = [];
889	  const records: Array<Record<string, unknown> | null> = [];
890	  items.forEach((it, idx) => {
891	    const at = `第 ${idx + 1} 项`;
892	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
893	      problems.push(`${at} 必须是对象`);
894	      records.push(null);
895	      return;
896	    }
897	    const rec = it as Record<string, unknown>;
898	    for (const k of Object.keys(rec)) {
