1487	async function cmdProcessWaitlist(args: string[]): Promise<void> {
1488	  const {values, positionals} = parseFlags(args, []);
1489	  if (values.size > 0) {
1490	    throw new UsageError(`process-waitlist 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
1491	  }
1492	  if (positionals.length > 0) {
1493	    throw new UsageError(`process-waitlist 不接受位置参数: ${positionals.join(' ')}`);
1494	  }
1495	
1496	  const file = activeDataFile;
1497	  const store = await loadStore(file);
1498	
1499	  // 已兑现/已取消项永不重新处理；只按登记顺序遍历等待项
1500	  const waiting = store.waitlist.filter((w) => w.status === 'waiting');
1501	  if (waiting.length === 0) {
1502	    // 明确说明且不改变记录或计数（不落盘）
1503	    if (store.waitlist.length === 0) {
1504	      console.log('候补队列为空，没有可处理的候补；记录与标识计数不变。');
1505	    } else {
1506	      console.log('候补队列中没有等待中的候补（均已兑现或已取消）；记录与标识计数不变。');
1507	    }
1508	    return;
1509	  }
1510	
1511	  // 本轮已选中项（即时预约标识在选中时分配，全部成功后一次性落盘；
1512	  // 若保存失败，磁盘原文件、记录与计数均不变）
1513	  const selected: Array<{w: WaitlistRec; bookingId: string; startMin: number; endMin: number}> = [];
1514	  const blocked: Array<{
1515	    w: WaitlistRec;
1516	    gaps: Array<{id: string; r: ResourceRec}>;
1517	    conflicts: PendingConflict[];
1518	  }> = [];
1519	
1520	  for (const w of waiting) {
1521	    const startMin = parseDateTime(w.start, '候补开始时间');
1522	    const endMin = parseDateTime(w.end, '候补结束时间');
1523	
1524	    // 1) 重查开放覆盖（资源开放区间可能已变化）
1525	    const gaps = findCoverageGaps(store, w.resourceIds, startMin, endMin);
1526	
1527	    // 2) 与当前全部有效预约（含系列成员，已取消不占用）求冲突
1528	    const wanted = new Set(w.resourceIds);
1529	    const conflicts: PendingConflict[] = [];
1530	    for (const b of store.bookings) {
1531	      if (b.status !== 'active') continue;
1532	      const bStart = parseDateTime(b.start, '预约开始时间');
1533	      const bEnd = parseDateTime(b.end, '预约结束时间');
1534	      if (!(bStart < endMin && startMin < bEnd)) continue;
1535	      const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1536	      if (shared.length > 0) conflicts.push({bookingId: b.id, start: b.start, end: b.end, shared});
1537	    }
1538	    // 3) 与本轮已选中项求冲突——后来者不能顶掉先选中者，顺序绝不改变
1539	    for (const s of selected) {
1540	      if (!(s.startMin < endMin && startMin < s.endMin)) continue;
1541	      const shared = s.w.resourceIds.filter((id) => wanted.has(id)).sort();
1542	      if (shared.length > 0) {
1543	        conflicts.push({
1544	          bookingId: s.bookingId,
1545	          start: s.w.start,
1546	          end: s.w.end,
1547	          shared,
1548	          fromWaitlistId: s.w.id,
1549	        });
1550	      }
1551	    }
1552	    conflicts.sort((a, b) => a.bookingId.localeCompare(b.bookingId));
1553	
1554	    if (gaps.length === 0 && conflicts.length === 0) {
1555	      // 全部资源可用才选中；受阻项跳过并继续检查后项
1556	      store.bookingSeq += 1;
1557	      const bookingId = `B${String(store.bookingSeq).padStart(4, '0')}`;
1558	      selected.push({w, bookingId, startMin, endMin});
1559	    } else {
1560	      blocked.push({w, gaps, conflicts});
1561	    }
1562	  }
1563	
1564	  if (selected.length === 0) {
1565	    // 没有可兑现项也成功：明确说明，不保存、不改变记录或计数
1566	    console.log(
1567	      `候补处理完成：本轮处理 ${waiting.length} 项等待候补，没有可兑现项（开放不足或仍有冲突），` +
1568	        '全部继续等待；记录、占用与标识计数不变。',
1569	    );
1570	    for (const {w, gaps, conflicts} of blocked) {
1571	      console.log(renderBlocked(store, w, gaps, conflicts));
1572	    }
1573	    return;
1574	  }
1575	
1576	  // 为每个选中项各生成一项普通预约（不加入系列、不改动原预约），
1577	  // 新预约、候补已兑现状态及关联预约标识一次性原子落盘后才报告成功。
1578	  for (const s of selected) {
1579	    store.bookings.push({
1580	      id: s.bookingId,
1581	      resourceIds: s.w.resourceIds,
1582	      start: s.w.start,
1583	      end: s.w.end,
1584	      status: 'active',
1585	    });
1586	    s.w.status = 'fulfilled';
1587	    s.w.bookingId = s.bookingId;
1588	  }
1589	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
1590	  await saveStore(file, store);
1591	
1592	  const selectedById = new Map(selected.map((s) => [s.w.id, s]));
1593	  const blockedById = new Map(blocked.map((b) => [b.w.id, b]));
1594	  console.log(
1595	    `候补处理完成：按登记顺序处理 ${waiting.length} 项等待候补，本轮兑现 ${selected.length} 项，` +
1596	      `${blocked.length} 项继续等待（已兑现/已取消项未参与）。`,
1597	  );
1598	  for (const w of waiting) { // 结果严格按队列顺序展示
1599	    const s = selectedById.get(w.id);
1600	    if (s) {
1601	      console.log(`- 兑现 ${w.id} → 新预约 ${s.bookingId}（普通预约，不属于任何系列）`);
1602	      console.log(`    时间: ${w.start} → ${w.end}`);
1603	      console.log(`    资源: ${formatResourceIds(store, w.resourceIds)}`);
1604	    } else {
1605	      const b = blockedById.get(w.id)!;
1606	      console.log(renderBlocked(store, w, b.gaps, b.conflicts));
1607	    }
1608	  }
1609	}
1610	
1611	function renderBlocked(
1612	  store: Store,
1613	  w: WaitlistRec,
1614	  gaps: Array<{id: string; r: ResourceRec}>,
1615	  conflicts: PendingConflict[],
1616	): string {
1617	  const lines = [`- 继续等待 ${w.id}：${w.start} → ${w.end}`];
1618	  if (gaps.length > 0) {
1619	    lines.push('    开放不足资源:');
1620	    for (const {id, r} of gaps) lines.push(`      - ${id}（${r.name}）`);
1621	  }
1622	  if (conflicts.length > 0) {
1623	    lines.push('    冲突预约（共同资源时间重叠）:');
1624	    for (const c of conflicts) {
1625	      const note = c.fromWaitlistId ? `（本轮新预约，兑现自候补 ${c.fromWaitlistId}）` : '';
1626	      lines.push(
1627	        `      - ${c.bookingId}${note}（${c.start} → ${c.end}）：共同资源 ${formatResourceIds(store, c.shared)}`,
1628	      );
1629	    }
1630	  }
1631	  return lines.join('\n');
1632	}
