function subtractSegments(segments: Array<[number,number]>, cuts: Array<[number,number]>): Array<[number,number]> {
  let result = segments;
  for (const [cs, ce] of cuts) {
    const next: Array<[number,number]> = [];
    for (const [s, e] of result) {
      if (ce <= s || cs >= e) { next.push([s, e]); continue; }
      if (cs > s) next.push([s, cs]);
      if (ce < e) next.push([ce, e]);
    }
    result = next;
  }
  return result;
}

function activeSuspensionsOf(store: Store, resourceId: string): SuspensionRec[] {
  return store.suspensions.filter((s) => s.resourceId === resourceId && s.status === 'active');
